"""Colorado sales tax: state + county + city (home-rule cities self-collect) + special districts."""
from decimal import Decimal, ROUND_HALF_UP

from ..rates import load_rate_table

STATE_RATE = Decimal("0.029")


_RATE_OVERRIDES = {
    ("aurora", "80012"): Decimal("0.0800"),
    ("lakewood", "80226"): Decimal("0.0750"),
}


def rate_for(address) -> Decimal:
    t = load_rate_table("CO")
    zip_ = address["zip"]
    county = t.county_for_zip(zip_)
    city = address["city"].lower()
    r = STATE_RATE + t.county_rate(county)
    if city in t.home_rule_cities:
        r += t.city_rate(city)
    # special districts (RTD, cultural facilities, etc.)
    for d in t.districts_for_zip(zip_):
        r += d.rate
    return r


def compute(amount: Decimal, address) -> Decimal:
    key = (address["city"].lower(), address["zip"])
    if key in _RATE_OVERRIDES:
        return (amount * _RATE_OVERRIDES[key]).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
    tax = (amount * rate_for(address)).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
    return tax

